INSERT INTO agents (id, tenant_id, project_id, name, description, model, instructions, tools, tool_count, enabled, created_by) VALUES
(9301,'intertec-systems-0c600f88',9001,'Banking Ops Copilot','On-call assistant for the payments and core banking night shift. Explains what broke and what to do, and can trigger pre-approved remediation only.','claude-sonnet-4','You assist the night-shift banking operations team. You may explain failures, correlate breaks across the payment hub, nostro and ledger, and rerun allowlisted jobs. You must never post financial entries, unblock a card or release a payment - those require a human approval gate. Every action you take is written to the immutable audit log.','["AutoOps run history","Runbook knowledge base","Rerun (allowlisted jobs)","Slack notify"]',4,1,'demo-seed'),
(9302,'intertec-systems-0c600f88',9001,'Compliance Research Analyst','Answers regulatory and internal-policy questions with citations, and pre-fills evidence packs for audit requests. Read-only by design.','claude-opus-4','You answer regulatory and internal policy questions for the compliance team. Every answer must cite a source circular or policy document. You are read-only: you never file, submit or attest to anything with the regulator. If the knowledge base does not cover a question, say so plainly rather than inferring an answer.','["Circular + policy knowledge base","Compliance report search","Audit log search"]',3,1,'demo-seed');
